module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

    reg [1:0] count;
    reg [9:0] sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 2'b0;
            sum <= 10'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0; // Default to 0 unless updated
            if (valid_in) begin
                sum <= sum + data_in;
                count <= count + 1;
                if (count == 2'd3) begin // After 4th data (0 to 3)
                    data_out <= sum + data_in; // Add current data_in to sum
                    valid_out <= 1'b1;
                    sum <= 10'b0;
                    count <= 2'b0;
                end
            end
        end
    end

endmodule

