                .A(A[4*i+4 : 4*i+1]),
                .B(B[4*i+4 : 4*i+1]),
                .S(S[4*i+4 : 4*i+1]),
                .G(G[i]),
                .P(P[i]),
                .Cin(C[i]),
                .Cout(C[i+1])
            );
        end
    endgenerate

    // Generate Carry Calculation
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & G[0]) | (P[1] & P[0] & C[0]);
