                            quotient <= {quotient[6:0], carry_out};
                            remainder <= temp_sub[7:0];
                            cnt <= cnt + 1;
                        end
                    end
                end

                DONE: begin
                    if (res_ready) begin
                        res_valid <= 0;
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

